// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.iteration.QueryExecutionDeadline;
import org.junit.jupiter.api.Test;

class NativeCancellationTokenDeadlineTest {

	@Test
	void capturedDeadlineCancelsParentAndWorkerOutsideItsThreadScope() throws Exception {
		try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(10);
				ExecutorService workers = Executors.newSingleThreadExecutor()) {
			NativeCancellationToken parent;
			try (QueryExecutionDeadline.Scope ignored = deadline.enter()) {
				parent = new NativeCancellationToken();
			}
			NativeCancellationToken worker = new NativeCancellationToken(parent);
			awaitExpiration(deadline);
			assertTrue(workers.submit(worker::isCancellationRequested).get(5, TimeUnit.SECONDS),
					"worker tokens must observe the parent's captured deadline without an installed thread scope");
			assertTrue(parent.isCancellationRequested());
		}
	}

	@Test
	void alreadyExpiredDeadlineCancelsNewToken() throws Exception {
		try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1)) {
			awaitExpiration(deadline);
			try (QueryExecutionDeadline.Scope ignored = deadline.enter()) {
				assertTrue(new NativeCancellationToken().isCancellationRequested(),
						"expiration before token creation cannot be lost");
			}
		}
	}

	@Test
	void nestedDeadlineScopeDoesNotReplaceCapturedDeadline() throws Exception {
		try (QueryExecutionDeadline outer = QueryExecutionDeadline.start(10);
				QueryExecutionDeadline inner = QueryExecutionDeadline.start(60_000)) {
			NativeCancellationToken token;
			try (QueryExecutionDeadline.Scope ignored = outer.enter()) {
				token = new NativeCancellationToken();
			}
			awaitExpiration(outer);
			try (QueryExecutionDeadline.Scope ignored = inner.enter()) {
				assertTrue(token.isCancellationRequested());
				assertFalse(new NativeCancellationToken().isCancellationRequested(),
						"an independent inner evaluation keeps its own deadline");
			}
		}
	}

	private static void awaitExpiration(QueryExecutionDeadline deadline) throws Exception {
		CompletableFuture<Void> expired = new CompletableFuture<>();
		try (QueryExecutionDeadline.Registration ignored = deadline.onExpiration(() -> expired.complete(null))) {
			expired.get(5, TimeUnit.SECONDS);
		}
	}
}
